-- ('Alice', 500)
-- ('Charlie', NULL)

-- Q1 Result:
-- SELECT EMPLOYEE.NAME, BONUS.BONUS FROM EMPLOYEE LEFT JOIN BONUS ON EMPLOYEE.EMPID = BONUS.EMPID WHERE BONUS < 1000 OR BONUS IS NULL;
-- Alice | 500
-- Charlie | NULL

-- Q2 Result:
-- WITH TEMP_TABLE AS ( SELECT EMPLOYEE.NAME, BONUS FROM EMPLOYEE LEFT JOIN BONUS ON EMPLOYEE.EMPID = BONUS.EMPID WHERE BONUS < 1000 OR BONUS IS NULL ) SELECT * FROM TEMP_TABLE;
-- Alice | 500
-- Charlie | NULL

