counterexample:
-- No counterexample can be generated under the given schema where Q1 and Q2 produce different results, as they are semantically equivalent. 
-- The following inserts would illustrate the equivalence:

-- Scenario 1: PRODUCT has 1 distinct product
-- Q1 result: {1, 2}
-- Q2 result: {1, 2}
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (101);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (1, 101);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (2, 101);

-- Scenario 2: PRODUCT has >1 distinct products (after clearing previous data)
-- Q1 result: {}
-- Q2 result: {}
-- DELETE FROM CUSTOMER; DELETE FROM PRODUCT;
-- INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (101);
-- INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (102);
-- INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (1, 101);
-- INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (2, 102);

-- Scenario 3: PRODUCT is empty (after clearing previous data)
-- Q1 result: {}
-- Q2 result: {}
-- DELETE FROM CUSTOMER; DELETE FROM PRODUCT;

